```c
static void ns_free(Sdb *s, SdbList *list) {
    ...
    if (in_list (list, s)) {
        return;
    }
    ls_append (list, s);
    ls_foreach (s->ns, it, ns) {
        deleted = 0;
        next.n = it->n;
        if (!in_list (list, ns)) {
            ls_delete (s->ns, it);
            free (ns->name);
            ns->name = NULL;
            deleted = 1;
            if (ns->sdb) {
                if (sdb_free (ns->sdb)) {
                    ns->sdb = NULL;
                    free (ns->name);
                    ns->name = NULL;
                }
            }
            ls_append (list, ns);
            ls_append (list, ns->sdb);
            ns_free (ns->sdb, list);
            sdb_free (ns->sdb);
        }
        if (!deleted) {
            sdb_free (ns->sdb);
            s->ns->free = NULL;
            ls_delete (s->ns, it);
        }
        free (ns);
        it = &next;
    }
    ls_free (s->ns);
    s->ns = NULL;
